    public static string Name(int id, string fallback) => Entries.TryGetValue(id, out var entry) ? entry.Name : fallback;
    public static string? Effect(int id, string? fallback) => Entries.TryGetValue(id, out var entry) ? entry.Effect : fallback;
    public static string? EnglishName(int id) => Entries.TryGetValue(id, out var entry) ? entry.EnglishName : null;

    private static readonly IReadOnlyDictionary<string, string> NamesByEnglish = Entries.Values
        .GroupBy(entry => entry.EnglishName, StringComparer.OrdinalIgnoreCase)
        .ToDictionary(group => group.Key, group => group.Key switch
        {
            "As One" => "Единство",
            "Embody Aspect" => "Воплощение аспекта",
            _ => group.First().Name,
        }, StringComparer.OrdinalIgnoreCase);

    public static string TranslateName(string name) => name switch
    {
        "As One" => "Единство",
        "Embody Aspect" => "Воплощение аспекта",
        _ => NamesByEnglish.GetValueOrDefault(name, name),
    };

    public static string SlotName(NamedChoice choice)
    {
        var separator = choice.Name.IndexOf('·');
        var name = separator >= 0 ? choice.Name[(separator + 1)..].Trim() : choice.Name;
        var slot = choice.Id == 2 ? "Скрытая" : $"Ячейка {choice.Id + 1}";
        return $"{slot} · {TranslateName(name)}";
    }
}
